 'fases' => [
   ['indagar', 'Cómo se llevan las cuentas hoy', 'Pregunta a quien haya manejado el dinero de una actividad del curso. Averigua qué anotaba, dónde y qué se le complicó.', 'Entrevista con al menos cinco datos concretos del método actual.', 40],
   ['desarrollar', 'Categorías y presupuesto', 'Define las categorías de gasto y el presupuesto de cada una. Decide qué hace el programa cuando una categoría se pasa.', 'Lista de categorías, presupuesto y regla de alerta.', 40],
   ['crear', 'Programar y llevar las cuentas', 'Implementa el gestor y lleva con él las cuentas reales de una actividad. Guarda los movimientos en archivo.', 'Archivo gastos.py y las cuentas reales cargadas.', 75],
   ['evaluar', 'Que cuadre al centavo', 'Compara tu saldo con el que llevó un compañero en papel. Si no cuadran, encuentra la causa exacta y corrígela.', 'Comparación de los dos saldos y explicación de la diferencia.', 45],
