 'fases' => [
   ['indagar', 'Qué ve un sensor', 'Investiga cómo distingue el negro del blanco un sensor infrarrojo. Prueba con distintos materiales y anota cuáles confunden al sensor.', 'Explicación del funcionamiento y lista de tres materiales que lo confunden.', 45],
   ['desarrollar', 'La tabla de verdad', 'Completa las cuatro combinaciones posibles de los dos sensores y decide la acción de cada una. Justifica el caso en que ninguno ve la línea.', 'Tabla de verdad completa con la justificación del caso perdido.', 40],
   ['crear', 'Programar y recorrer', 'Implementa la lógica y haz que el robot recorra la pista tres veces. Cuenta cuántas veces se sale en cada vuelta.', 'Programa funcionando y registro de tres vueltas.', 80],
   ['evaluar', 'Bajar las salidas', 'Ajusta velocidad o tiempos de giro y vuelve a medir. Documenta qué cambio produjo la mayor mejora y por qué.', 'Tabla de mediciones antes y después con el análisis del ajuste.', 45],
 ],
 'recursos' => [
   ['plantilla', 'Pista de línea negra', 'Trazado imprimible con recta, curva suave y curva cerrada.'],
   ['codigo', 'simulador_linea.py', 'Simulador de rejilla para trabajar sin placa física.'],
 ]],

['codigo' => 'VCP-7-16', 'titulo' => 'La IA como corrector: qué acepto y qué rechazo',
 'objeto' => 'el texto corregido con criterio',
 'resumen' => 'Pedir a un asistente que corrija un texto propio y decidir sugerencia por sugerencia cuál se aplica y por qué.',
 'descripcion' => '<p>El estudiante entrega al asistente un texto suyo de otra asignatura y le pide correcciones de ortografía, claridad y estructura. Cada sugerencia se anota y se decide: se acepta, se modifica o se rechaza, siempre con el motivo escrito.</p><p>El aprendizaje aparece al rechazar: cuando el asistente propone una palabra más elegante pero que el estudiante no usaría nunca, entender por qué rechazarla es entender qué es la voz propia. El texto final sigue sonando a quien lo escribió.</p>',
 'pregunta' => '¿Sigue siendo mío un texto que otro corrigió?',
 'contexto' => 'Expresión personal y cultural', 'concepto' => 'Comunicación',
 'perfil' => 'Íntegro|Reflexivo|Buen comunicador', 'atl' => 'Reflexión|Pensamiento crítico',
 'objetivos' => 'Distinguir corrección de reescritura|Evaluar una sugerencia antes de aplicarla|Conservar la voz propia en un texto revisado|Declarar la asistencia recibida con detalle',
 'entregables' => 'Texto original y texto final|Tabla de todas las sugerencias con la decisión y el motivo|Reflexión sobre las sugerencias rechazadas',
 'lenguaje' => 'Lenguaje natural', 'dificultad' => 'intermedio', 'sesiones' => 3, 'horas' => 3.0, 'ia' => 1,
 'codigo_inicial' => "# Tabla de sugerencias\n# | # | Que sugirio | Tipo (ortografia/claridad/estilo) | Decision | Motivo |\n#\n# Regla: si rechazas menos de 3 sugerencias, probablemente no estas leyendo,\n# solo aceptando.",
 'fases' => [
   ['indagar', 'Tipos de corrección', 'Clasifica diez correcciones posibles en ortográficas, de claridad y de estilo. Explica cuáles son objetivas y cuáles son cuestión de gusto.', 'Clasificación de diez correcciones con la distinción justificada.', 40],
   ['desarrollar', 'Qué le voy a pedir', 'Redacta la instrucción: qué tipos de corrección quieres, cuáles no, y que te explique el motivo de cada una en vez de reescribir el texto.', 'Instrucción redactada con los límites explícitos.', 35],
   ['crear', 'Corregir con criterio', 'Somete tu texto y registra cada sugerencia. Decide una por una y aplica solo las que aceptes o modifiques.', 'Tabla completa de sugerencias y texto final.', 60],
   ['evaluar', '¿Suena a mí?', 'Pide a un compañero que lea el texto original y el final y diga si los escribió la misma persona. Analiza las sugerencias que rechazaste.', 'Opinión del compañero y reflexión sobre los rechazos.', 40],
 ],
 'recursos' => [
   ['plantilla', 'Registro de sugerencias', 'Sugerencia, tipo, decisión y motivo.'],
 ]],

